PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS stores(id INTEGER PRIMARY KEY,store_name TEXT NOT NULL,platform TEXT NOT NULL,owner_name TEXT,remark TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,store_id INTEGER NOT NULL,name TEXT NOT NULL,platform TEXT NOT NULL,category TEXT,price REAL NOT NULL DEFAULT 0,cost REAL NOT NULL DEFAULT 0,target_audience TEXT,selling_points TEXT,product_url TEXT,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS product_skus(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,sku_code TEXT NOT NULL,sku_name TEXT NOT NULL,price REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY,sku_id INTEGER UNIQUE NOT NULL,stock_qty INTEGER NOT NULL DEFAULT 0,locked_qty INTEGER NOT NULL DEFAULT 0,warning_threshold INTEGER NOT NULL DEFAULT 10,updated_at TEXT NOT NULL,FOREIGN KEY(sku_id) REFERENCES product_skus(id));
CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER PRIMARY KEY,sku_id INTEGER NOT NULL,movement_type TEXT NOT NULL,change_qty INTEGER NOT NULL,before_qty INTEGER NOT NULL,after_qty INTEGER NOT NULL,reason_text TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(sku_id) REFERENCES product_skus(id));
CREATE TABLE IF NOT EXISTS competitors(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,name TEXT NOT NULL,platform TEXT,url TEXT,price REAL,selling_points TEXT,created_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS product_diagnoses(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,positioning TEXT,price_band TEXT,audience_insights TEXT,pain_points TEXT,selling_point_analysis TEXT,risks TEXT,recommendations TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS creative_plans(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,plan_type TEXT NOT NULL,title TEXT NOT NULL,content_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS generation_jobs(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,creative_plan_id INTEGER,job_kind TEXT NOT NULL,job_status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,result_json TEXT,error_message TEXT,created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS generation_job_events(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL,event_type TEXT NOT NULL,event_message TEXT,created_at TEXT NOT NULL,FOREIGN KEY(job_id) REFERENCES generation_jobs(id));
CREATE TABLE IF NOT EXISTS generated_assets(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,creative_plan_id INTEGER,job_id INTEGER,asset_type TEXT NOT NULL,asset_url TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending',version_no INTEGER NOT NULL DEFAULT 1,usage_scene TEXT,score REAL,tags_json TEXT,remark TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(job_id) REFERENCES generation_jobs(id));
CREATE TABLE IF NOT EXISTS performance_records(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,impressions INTEGER NOT NULL,clicks INTEGER NOT NULL,conversions INTEGER NOT NULL,spend REAL NOT NULL,revenue REAL NOT NULL,notes TEXT,created_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS review_reports(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,period_start TEXT,period_end TEXT,summary_text TEXT,insights_json TEXT,next_actions_json TEXT,created_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS promotion_links(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,link_name TEXT NOT NULL,target_url TEXT NOT NULL,tracking_code TEXT UNIQUE NOT NULL,scene_text TEXT,click_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS ad_recommendations(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL,summary_text TEXT NOT NULL,objective_text TEXT,audience_segments_json TEXT,budget_plan_json TEXT,confirm_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id));
